/**
 * Splits the third-party notices (the root THIRD-PARTY-NOTICES.txt, generated by scripts/build-notices.mjs) into entries: Settings → About → Third-party notices
 * lists the name, version and license per component, and a click shows the license text (a whole page of English would be unreadable for people who do not read English, so the surrounding text follows the interface language while the license text stays English).
 * The format follows the generating script: each entry has a header block (a line of 78 "=", "name version", License:, Source:, for a component shipped with one platform's
 * app only an Only in: line, a line of "="), then a blank line and the license text, up to the next header block
 */
export type Notice = {
  name: string;
  version: string;
  license: string;
  sources: string[];
  text: string;
  /** The platforms whose app ships it ("Windows", "macOS"); undefined = every one */
  only?: string[];
};

const RULE = "=".repeat(78);
const LICENSE = "License: ";
const SOURCE = "Source: ";
const ONLY = "Only in: ";

export function parseNotices(file: string): Notice[] {
  const lines = file.replace(/\r\n?/g, "\n").split("\n");
  /** Where each header block starts, and how many lines it has (5, or 6 with an Only in: line) */
  const heads: { at: number; size: number }[] = [];
  for (let i = 0; i + 4 < lines.length; i++) {
    if (lines[i] !== RULE || !lines[i + 2].startsWith(LICENSE) || !lines[i + 3].startsWith(SOURCE)) continue;
    if (lines[i + 4] === RULE) heads.push({ at: i, size: 5 });
    else if (lines[i + 4].startsWith(ONLY) && lines[i + 5] === RULE) heads.push({ at: i, size: 6 });
  }
  return heads.map(({ at, size }, k) => {
    // The version has no spaces while the name does (".NET Windows Desktop Runtime (WPF, Windows Forms)"): what follows the last space is the version
    const title = lines[at + 1];
    const space = title.lastIndexOf(" ");
    const notice: Notice = {
      name: title.slice(0, space),
      version: title.slice(space + 1),
      license: lines[at + 2].slice(LICENSE.length),
      sources: lines[at + 3].slice(SOURCE.length).split(", "),
      text: lines
        .slice(at + size, heads[k + 1]?.at ?? lines.length)
        .join("\n")
        .trim(),
    };
    if (size === 6) notice.only = lines[at + 4].slice(ONLY.length).split(", ");
    return notice;
  });
}

/** The notices of the components this platform's app ships: the Mac app has none of the Windows shell's runtime and libraries */
export function noticesFor(notices: Notice[], platform: "windows" | "mac"): Notice[] {
  const name = platform === "mac" ? "macOS" : "Windows";
  return notices.filter((n) => !n.only || n.only.includes(name));
}
